    };
    // Used to determine whether we are adding or editing
    this.isEditMode = false;
  }
  // =========================================================
  // Lifecycle
  // =========================================================
  ngOnInit() {
    this.filteredStudents = [...this.students];
  }
  // =========================================================
  // Statistics
  // =========================================================
  get activeStudentsCount() {
    return this.students.filter(student => student.status === 'Active').length;
  }
  get inactiveStudentsCount() {
    return this.students.filter(student => student.status === 'Inactive').length;
  }
  get newStudentsCount() {
    const currentMonth = new Date().getMonth();
    const currentYear = new Date().getFullYear();
    return this.students.filter(student => {
      const createdDate = new Date(student.createdAt);
      return createdDate.getMonth() === currentMonth && createdDate.getFullYear() === currentYear;
    }).length;
  }
  // =========================================================
  // Get Student Initials
  // =========================================================
  getInitials(name) {
    return name.split(' ').filter(word => word.length > 0).map(word => word.charAt(0)).join('').substring(0, 2).toUpperCase();
  }
  // =========================================================
  // Filters
  // =========================================================
  applyFilters() {
    const search = this.searchValue.toLowerCase().trim();
    this.filteredStudents = this.students.filter(student => {
      const matchesSearch = !search || student.name.toLowerCase().includes(search) || student.email.toLowerCase().includes(search) || student.phone.toLowerCase().includes(search);
      const matchesGroup = !this.selectedGroup || student.group === this.selectedGroup;
      const matchesStatus = !this.selectedStatus || student.status === this.selectedStatus;
      return matchesSearch && matchesGroup && matchesStatus;
    });
  }
  // =========================================================
  // Add Student
  // =========================================================
  onAddStudentClick() {
    this.isEditMode = false;
