import { Component, OnInit } from '@angular/core';

interface Student {
  name: string;
  email: string;
  group: string;
  phone: string;
  status: 'Active' | 'Inactive';
  createdAt: Date;
}

@Component({
  selector: 'app-students',
  templateUrl: './students.component.html',
  styleUrls: ['./students.component.css']
})
export class StudentsComponent implements OnInit {

  // =========================================================
  // Students Data
  // =========================================================

  students: Student[] = [
    {
      name: 'Ahmed Hassan',
      email: 'ahmed@gmail.com',
      group: 'Group A',
      phone: '01012345678',
      status: 'Active',
      createdAt: new Date()
    },
    {
      name: 'Mohamed Omar',
      email: 'mohamed@gmail.com',
      group: 'Group B',
      phone: '01098765432',
      status: 'Active',
      createdAt: new Date()
    },
    {
      name: 'Youssef Farag',
      email: 'youssef@gmail.com',
      group: 'Group C',
      phone: '01055555555',
      status: 'Inactive',
      createdAt: new Date()
    }
  ];

  // Students displayed after filtering
  filteredStudents: Student[] = [];

  // Available groups
  groups: string[] = [
    'Group A',
    'Group B',
    'Group C'
  ];

  // =========================================================
  // Filters
  // =========================================================

  searchValue: string = '';
  selectedGroup: string = '';
  selectedStatus: string = '';

  // =========================================================
  // Modals
  // =========================================================

  isModalOpen: boolean = false;
  isDetailsModalOpen: boolean = false;

  selectedStudent: Student | null = null;

  // =========================================================
  // New / Edited Student
  // =========================================================

  newStudent = {
    name: '',
    email: '',
    group: '',
    phone: '',
    status: 'Active' as 'Active' | 'Inactive'
  };

  // Used to determine whether we are adding or editing
  isEditMode: boolean = false;


  // =========================================================
  // Lifecycle
  // =========================================================

  ngOnInit(): void {
    this.filteredStudents = [...this.students];
  }


  // =========================================================
  // Statistics
  // =========================================================

  get activeStudentsCount(): number {
    return this.students.filter(
      student => student.status === 'Active'
    ).length;
  }


  get inactiveStudentsCount(): number {
    return this.students.filter(
      student => student.status === 'Inactive'
    ).length;
  }


  get newStudentsCount(): number {

    const currentMonth = new Date().getMonth();
    const currentYear = new Date().getFullYear();

    return this.students.filter(student => {

      const createdDate = new Date(student.createdAt);

      return (
        createdDate.getMonth() === currentMonth &&
        createdDate.getFullYear() === currentYear
      );

    }).length;
  }


  // =========================================================
  // Get Student Initials
  // =========================================================

  getInitials(name: string): string {

    return name
      .split(' ')
      .filter(word => word.length > 0)
      .map(word => word.charAt(0))
      .join('')
      .substring(0, 2)
      .toUpperCase();

  }


  // =========================================================
  // Filters
  // =========================================================

  applyFilters(): void {

    const search = this.searchValue
      .toLowerCase()
      .trim();

    this.filteredStudents = this.students.filter(student => {

      const matchesSearch =
        !search ||
        student.name.toLowerCase().includes(search) ||
        student.email.toLowerCase().includes(search) ||
        student.phone.toLowerCase().includes(search);

      const matchesGroup =
        !this.selectedGroup ||
        student.group === this.selectedGroup;

      const matchesStatus =
        !this.selectedStatus ||
        student.status === this.selectedStatus;

      return (
        matchesSearch &&
        matchesGroup &&
        matchesStatus
      );

    });

  }


  // =========================================================
  // Add Student
  // =========================================================

  onAddStudentClick(): void {

    this.isEditMode = false;

    this.selectedStudent = null;

    this.newStudent = {
      name: '',
      email: '',
      group: '',
      phone: '',
      status: 'Active'
    };

    this.isModalOpen = true;

  }


  // =========================================================
  // Close Add/Edit Modal
  // =========================================================

  closeModal(): void {

    this.isModalOpen = false;

    this.selectedStudent = null;

    this.isEditMode = false;

  }


  // =========================================================
  // Save Student
  // =========================================================

  saveStudent(): void {

    // Basic validation
    if (
      !this.newStudent.name.trim() ||
      !this.newStudent.email.trim() ||
      !this.newStudent.group
    ) {
      return;
    }


    // =======================================================
    // Edit Existing Student
    // =======================================================

    if (this.isEditMode && this.selectedStudent) {

      this.selectedStudent.name = this.newStudent.name.trim();
      this.selectedStudent.email = this.newStudent.email.trim();
      this.selectedStudent.group = this.newStudent.group;
      this.selectedStudent.phone = this.newStudent.phone.trim();
      this.selectedStudent.status = this.newStudent.status;

    }


    // =======================================================
    // Add New Student
    // =======================================================

    else {

      const student: Student = {

        name: this.newStudent.name.trim(),

        email: this.newStudent.email.trim(),

        group: this.newStudent.group,

        phone: this.newStudent.phone.trim(),

        status: this.newStudent.status,

        createdAt: new Date()

      };

      this.students.push(student);

    }


    // Refresh table
    this.applyFilters();

    // Close modal
    this.closeModal();

  }


  // =========================================================
  // View Student
  // =========================================================

  viewStudent(student: Student): void {

    this.selectedStudent = student;

    this.isDetailsModalOpen = true;

  }


  // =========================================================
  // Close Details Modal
  // =========================================================

  closeDetailsModal(): void {

    this.isDetailsModalOpen = false;

    this.selectedStudent = null;

  }


  // =========================================================
  // Edit Student
  // =========================================================

  editStudent(student: Student): void {

    this.selectedStudent = student;

    this.isEditMode = true;

    this.newStudent = {

      name: student.name,

      email: student.email,

      group: student.group,

      phone: student.phone,

      status: student.status

    };

    this.isModalOpen = true;

  }


  // =========================================================
  // Delete Student
  // =========================================================

  deleteStudent(student: Student): void {

    const index = this.students.indexOf(student);

    if (index !== -1) {

      this.students.splice(index, 1);

      this.applyFilters();

    }

  }

}
<section class="students-page">

  <!-- ==================== Header ==================== -->
  <div class="students-header-banner">
    <div class="students-page__header">

      <div>
        <h2 class="students-page__title">Students</h2>

        <p class="students-page__subtitle">
          Manage and monitor all students in your learning center.
        </p>
      </div>

      <div class="students-page__actions">
        <button
          type="button"
          class="btn btn--primary"
          (click)="onAddStudentClick()"
        >
          <svg
            width="16"
            height="16"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="2"
          >
            <path
              d="M12 5v14M5 12h14"
              stroke-linecap="round"
            ></path>
          </svg>

          Add Student
        </button>
      </div>

    </div>
  </div>


  <!-- ==================== Statistics ==================== -->
  <div class="stats-grid">

    <!-- Total Students -->
    <div class="stat-card">
      <div class="stat-icon stat-icon--blue">
        <i class="fa-solid fa-user-graduate"></i>
      </div>

      <div class="stat-content">
        <span class="stat-title">Total Students</span>
        <strong>{{ students.length }}</strong>
        <span class="stat-description">All students</span>
      </div>
    </div>


    <!-- Active Students -->
    <div class="stat-card">
      <div class="stat-icon stat-icon--green">
        <i class="fa-solid fa-user-check"></i>
      </div>

      <div class="stat-content">
        <span class="stat-title">Active Students</span>
        <strong>{{ activeStudentsCount }}</strong>
        <span class="stat-description">Currently active</span>
      </div>
    </div>


    <!-- Inactive Students -->
    <div class="stat-card">
      <div class="stat-icon stat-icon--orange">
        <i class="fa-solid fa-user-clock"></i>
      </div>

      <div class="stat-content">
        <span class="stat-title">Inactive Students</span>
        <strong>{{ inactiveStudentsCount }}</strong>
        <span class="stat-description">Currently inactive</span>
      </div>
    </div>


    <!-- New Students -->
    <div class="stat-card">
      <div class="stat-icon stat-icon--purple">
        <i class="fa-solid fa-user-plus"></i>
      </div>

      <div class="stat-content">
        <span class="stat-title">New Students</span>
        <strong>{{ newStudentsCount }}</strong>
        <span class="stat-description">This month</span>
      </div>
    </div>

  </div>


  <!-- ==================== Students List ==================== -->
  <div class="students-card">

    <!-- Card Header -->
    <div class="students-card__header">

      <div>
        <h3>Students List</h3>
        <p>{{ filteredStudents.length }} students found</p>
      </div>


      <!-- Filters -->
      <div class="students-filters">

        <!-- Group Filter -->
        <select
          [(ngModel)]="selectedGroup"
          (change)="applyFilters()"
        >
          <option value="">All Groups</option>

          <option
            *ngFor="let group of groups"
            [value]="group"
          >
            {{ group }}
          </option>
        </select>


        <!-- Status Filter -->
        <select
          [(ngModel)]="selectedStatus"
          (change)="applyFilters()"
        >
          <option value="">All Status</option>
          <option value="Active">Active</option>
          <option value="Inactive">Inactive</option>
        </select>


        <!-- Search -->
        <div class="search-box">

          <svg
            width="16"
            height="16"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="2"
          >
            <circle
              cx="11"
              cy="11"
              r="8"
            ></circle>

            <path
              d="m21 21-4.3-4.3"
            ></path>
          </svg>

          <input
            type="text"
            placeholder="Search students..."
            [(ngModel)]="searchValue"
            (input)="applyFilters()"
          />

        </div>

      </div>

    </div>


    <!-- ==================== Students Table ==================== -->
    <div class="table-wrapper">

      <table class="students-table">

        <thead>
          <tr>
            <th>STUDENT</th>
            <th>EMAIL</th>
            <th>GROUP</th>
            <th>PHONE</th>
            <th>STATUS</th>
            <th>ACTIONS</th>
          </tr>
        </thead>


        <tbody>

          <!-- Student Rows -->
          <tr
            *ngFor="let student of filteredStudents"
          >

            <!-- Student -->
            <td>

              <div class="student-cell">

                <div class="student-avatar">
                  {{ getInitials(student.name) }}
                </div>

                <div class="student-info">
                  <strong>{{ student.name }}</strong>
                  <span>Student</span>
                </div>

              </div>

            </td>


            <!-- Email -->
            <td>
              <span class="text-muted">
                {{ student.email }}
              </span>
            </td>


            <!-- Group -->
            <td>
              <span class="group-badge">
                {{ student.group }}
              </span>
            </td>


            <!-- Phone -->
            <td>
              {{ student.phone }}
            </td>


            <!-- Status -->
            <td>

              <span
                class="status-badge"
                [class.status-badge--active]="student.status === 'Active'"
                [class.status-badge--inactive]="student.status === 'Inactive'"
              >
                <span></span>
                {{ student.status }}
              </span>

            </td>


            <!-- Actions -->
            <td>

              <div class="actions">

                <!-- View -->
                <button
                  type="button"
                  title="View"
                  (click)="viewStudent(student)"
                >
                  <i class="fa-regular fa-eye"></i>
                </button>


                <!-- Edit -->
                <button
                  type="button"
                  title="Edit"
                  (click)="editStudent(student)"
                >
                  <i class="fa-solid fa-pen"></i>
                </button>


                <!-- Delete -->
                <button
                  type="button"
                  title="Delete"
                  (click)="deleteStudent(student)"
                >
                  <i class="fa-regular fa-trash-can"></i>
                </button>

              </div>

            </td>

          </tr>


          <!-- ==================== Empty State ==================== -->
          <tr *ngIf="filteredStudents.length === 0">

            <td
              colspan="6"
              class="empty-state"
            >

              <div class="empty-state__icon">
                <i class="fa-solid fa-user-graduate"></i>
              </div>

              <strong>No students found</strong>

              <span>
                Try changing your search or filters.
              </span>

            </td>

          </tr>

        </tbody>

      </table>

    </div>

  </div>

</section>


<!-- ========================================================= -->
<!-- Add Student Modal -->
<!-- ========================================================= -->

<div
  class="modal-overlay"
  *ngIf="isModalOpen"
>

  <div class="modal-card">

    <h3>New Student</h3>


    <!-- Student Name -->
    <div class="form-group">

      <label>Student Name</label>

      <input
        type="text"
        [(ngModel)]="newStudent.name"
        placeholder="Enter student name"
      />

    </div>


    <!-- Email -->
    <div class="form-group">

      <label>Email</label>

      <input
        type="email"
        [(ngModel)]="newStudent.email"
        placeholder="Enter email"
      />

    </div>


    <!-- Group -->
    <div class="form-group">

      <label>Group</label>

      <select [(ngModel)]="newStudent.group">

        <option value="">
          Select group
        </option>

        <option
          *ngFor="let group of groups"
          [value]="group"
        >
          {{ group }}
        </option>

      </select>

    </div>


    <!-- Phone -->
    <div class="form-group">

      <label>Phone</label>

      <input
        type="text"
        [(ngModel)]="newStudent.phone"
        placeholder="Enter phone number"
      />

    </div>


    <!-- Status -->
    <div class="form-group">

      <label>Status</label>

      <select [(ngModel)]="newStudent.status">

        <option value="Active">
          Active
        </option>

        <option value="Inactive">
          Inactive
        </option>

      </select>

    </div>


    <!-- Modal Actions -->
    <div class="modal-actions">

      <button
        type="button"
        class="btn btn--ghost-dark"
        (click)="closeModal()"
      >
        Cancel
      </button>


      <button
        type="button"
        class="btn btn--primary modal-save-btn"
        (click)="saveStudent()"
      >
        Save Student
      </button>

    </div>

  </div>

</div>


<!-- ========================================================= -->
<!-- Student Details Modal -->
<!-- ========================================================= -->

<div
  class="modal-overlay"
  *ngIf="isDetailsModalOpen && selectedStudent"
>

  <div class="modal-card">

    <h3>Student Details</h3>


    <div class="student-details">

      <div>
        <strong>Student Name:</strong>
        {{ selectedStudent.name }}
      </div>

      <div>
        <strong>Email:</strong>
        {{ selectedStudent.email }}
      </div>

      <div>
        <strong>Group:</strong>
        {{ selectedStudent.group }}
      </div>

      <div>
        <strong>Phone:</strong>
        {{ selectedStudent.phone }}
      </div>

      <div>
        <strong>Status:</strong>
        {{ selectedStudent.status }}
      </div>

    </div>


    <!-- Modal Actions -->
    <div class="modal-actions">

      <button
        type="button"
        class="btn btn--primary modal-save-btn"
        (click)="closeDetailsModal()"
      >
        Close
      </button>

    </div>

  </div>

</div>
